-- >>> repository file, byte for byte
-- V2.0 (mission A2, 26 November 2026) — consolidation of the canonical packages release-v2-01 to release-v2-07.
--
-- 1. The account export (« Exporter toutes mes données », public.export_own_data) gains the two kinds of personal data the
--    lots V1.6.4 and V1.6.5 store but did not export: the history import batches with the result of each row
--    (private.titan_import_batches / titan_import_batch_rows: file name and fingerprint, outcome, reason, withdrawal) and the
--    synchronisation runs of the connected sources (private.titan_source_runs: Santé Connect readings, Garmin pushes). It wraps
--    the export chain like the V1.5 and V1.7.7 packages: every earlier section is kept.
-- 2. Hygiene: the V1.6.5 trigger function private.titan_source_consent_revoked_by() kept PostgreSQL's default EXECUTE grant to
--    PUBLIC (a trigger function cannot be called outside its trigger; revoking changes nothing for the trigger).
-- 3. A guard that refuses the whole package if the export chain lost one of the sections main and the lots export, if a private
--    function is executable by anon: the transaction aborts and nothing is kept. (The lot flags stay absent = closed; that is
--    checked by the rehearsal and by the owner's activation procedure, not here.)
--
-- Additive and idempotent. The caller owns the transaction: never BEGIN/COMMIT here.
-- Rollback: drop function private.titan_export_extras_v1(uuid); alter function private.titan_export_extras_before_v2_v1(uuid)
-- rename to titan_export_extras_v1; (the grant of 2. needs no rollback).

revoke all on function private.titan_source_consent_revoked_by() from public, anon, authenticated;

do $$ begin
  if to_regprocedure('private.titan_export_extras_before_v2_v1(uuid)') is null then
    alter function private.titan_export_extras_v1(uuid) rename to titan_export_extras_before_v2_v1;
  end if;
end $$;
create or replace function private.titan_export_extras_v1(p_uid uuid)
returns jsonb language sql stable security definer set search_path = '' as $$
  select private.titan_export_extras_before_v2_v1(p_uid) || jsonb_build_object(
    'importBatches', coalesce((
      select jsonb_agg(jsonb_build_object('id', b.id, 'format', b.format, 'file_name', b.file_name, 'file_hash', b.file_hash, 'total_rows', b.total_rows,
        'status', b.status, 'created_at', b.created_at, 'updated_at', b.updated_at, 'finished_at', b.finished_at, 'withdrawn_at', b.withdrawn_at,
        'withdraw_report', b.withdraw_report,
        'rows', coalesce((
          select jsonb_agg(jsonb_build_object('row_no', r.row_no, 'outcome', r.outcome, 'reason', r.reason, 'external_id', r.external_id, 'log_id', r.log_id,
            'log_revision', r.log_revision, 'needs_review', r.needs_review, 'withdrawn', r.withdrawn, 'at', r.at) order by r.row_no)
          from private.titan_import_batch_rows r where r.batch_id = b.id), '[]'::jsonb)) order by b.created_at)
      from private.titan_import_batches b where b.user_id = p_uid), '[]'::jsonb),
    'sourceRuns', coalesce((
      select jsonb_agg(jsonb_build_object('source', s.source, 'kind', s.kind, 'day', s.day, 'started_at', s.started_at, 'finished_at', s.finished_at,
        'window_from', s.window_from, 'window_to', s.window_to, 'outcome', s.outcome, 'error_code', s.error_code, 'counts', s.counts, 'excluded', s.excluded)
        order by s.started_at, s.id)
      from private.titan_source_runs s where s.user_id = p_uid), '[]'::jsonb));
$$;
revoke all on function private.titan_export_extras_before_v2_v1(uuid), private.titan_export_extras_v1(uuid) from public, anon, authenticated;

do $titan_v2_guard$
declare
  v_extras jsonb := private.titan_export_extras_v1(gen_random_uuid());
  v_social jsonb := private.titan_social_export_v1(gen_random_uuid());
  v_missing text[];
  v_open text;
begin
  select array_agg(k order by k) into v_missing from unnest(array[
    -- main (journey, cadence, capsules, chapters, social layers, LIVE, coaching of V1.1)
    'adventureRpg', 'buddies', 'cadenceWeekClaims', 'challengeResults', 'clubAnnouncements', 'clubReports', 'clubs', 'coachCheckins', 'coachMessages',
    'coachTemplates', 'commonQuests', 'dailyIntents', 'faction', 'garminLink', 'journey', 'journeyVerifiedDailyActivity', 'lifeChapters', 'pantheon',
    'pioneer', 'pollVotes', 'rankingOptIn', 'roadmapVotes', 'routes', 'seasons', 'timeCapsules', 'worldGoals',
    -- V1.5.0 to V1.5.5
    'adventureBranches', 'adventureGuardians', 'adventureConsequences', 'adventureConsequenceEvents', 'adventureQuests', 'adventureRuns', 'adventureChronicleEvents',
    -- V1.7.7
    'places',
    -- V1.9.2 to V1.9.6
    'coachFeedback', 'coachReviewDrafts', 'coachPrograms', 'coachPlans', 'coachCycleReports', 'coachGroups',
    -- this package (V1.6.4, V1.6.5)
    'importBatches', 'sourceRuns']) k where not v_extras ? k;
  if v_missing is not null then raise exception 'V2 export chain lost sections: %', v_missing; end if;
  select array_agg(k order by k) into v_missing from unnest(array['cordeeTitles', 'friendInvites',
    'cordeeRelays', 'cordeeRelayTurns', 'cordeeSuites', 'clubSeasons', 'clubMatches', 'clubAgenda']) k where not v_social ? k;
  if v_missing is not null then raise exception 'V2 social export lost sections: %', v_missing; end if;
  if position('private.titan_export_extras_v1(v_uid)' in pg_get_functiondef('public.export_own_data()'::regprocedure)) = 0
     or position('private.titan_social_export_v1(v_uid)' in pg_get_functiondef('public.export_own_data()'::regprocedure)) = 0 then
    raise exception 'public.export_own_data no longer reads the export chain';
  end if;
  select string_agg(p.oid::regprocedure::text, ', ') into v_open from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'private' and has_function_privilege('anon', p.oid, 'EXECUTE')
     -- granted to anon on purpose by main (RLS policy helpers, the analytics payload contract of 20261010163122)
     and p.oid::regprocedure::text not in ('private.titan_is_admin(uuid)', 'private.titan_is_moderator_or_admin(uuid)', 'private.titan_admin_role_for(uuid)',
       'private.titan_analytics_payload_valid_v300(text,text,text,text,jsonb)');
  if v_open is not null then raise exception 'private functions executable by anon: %', v_open; end if;
end $titan_v2_guard$;
